
const IMAGE_MAP = {"back": "data:image/png;base64,", "bulgarian": "data:image/png;base64,", "front": "data:image/png;base64,", "side_step": "data:image/png;base64,", "sumo": "data:image/png;base64,"};

const EXERCISES = [
  { id:'back', name:'Back Squat', type:'bilateral', coefficient:0.70, image: IMAGE_MAP.back },
  { id:'bulgarian', name:'Bulgarian Squat', type:'unilateral', coefficient:0.85, image: IMAGE_MAP.bulgarian },
  { id:'front', name:'Front Squat', type:'bilateral', coefficient:0.70, image: IMAGE_MAP.front },
  { id:'side_step', name:'Side Step', type:'unilateral', coefficient:0.85, image: IMAGE_MAP.side_step },
  { id:'sumo', name:'Sumo Squat', type:'bilateral', coefficient:0.70, image: IMAGE_MAP.sumo },
];

const ONBOARDING = [
  {
    title: 'Welcome to Squat Tribe',
    body: 'A simple, smart way to build strength at home using squats. The app guides your training, times your work and rest, and tracks your progress for you.',
  },
  {
    title: 'Why squats matter',
    body: 'Squats train your legs, hips and core together. Building squat strength can improve balance, support joints, make daily movement easier, and build real usable strength.',
  },
  {
    title: 'How a session works',
    body: 'You begin with one Anchor Set, rest for the same amount of time, then complete short Myo sets. The app uses your performance to guide the rest of the session.',
  },
  {
    title: 'Training that adapts',
    body: 'Some days you feel stronger than others. Squat Tribe adjusts to your current capacity so you can train hard, recover well, and keep progressing.',
  },
  {
    title: 'The Pentagon Protocol',
    body: 'You rotate through five squat variations to build balanced lower-body strength and reduce repeated strain on one pattern.',
  },
  {
    title: 'Unilateral rule',
    body: 'For Bulgarian Squat and Side Step, always begin with your weaker leg. The app will ask you to choose your weaker leg at the start of those sessions.',
  },
];

const $ = (sel) => document.querySelector(sel);
const app = $('#app');

const defaultState = {
  onboarded: false,
  onboardingIndex: 0,
  user: { bodyweight: '', defaultLoad: '0' },
  rotationMode: 'fixed',
  pointer: 0,
  sessions: [],
  redFlag: false,
  draft: null,
  view: 'onboarding',
};

function loadState() {
  try {
    const raw = localStorage.getItem('squatTribeState');
    if (!raw) return structuredClone(defaultState);
    const parsed = JSON.parse(raw);
    return { ...structuredClone(defaultState), ...parsed };
  } catch {
    return structuredClone(defaultState);
  }
}
let state = loadState();
state.view = state.onboarded ? 'home' : 'onboarding';

function saveState() {
  localStorage.setItem('squatTribeState', JSON.stringify(state));
}

function vibrate(pattern){ if (navigator.vibrate) navigator.vibrate(pattern); }

function todayStr() {
  const d = new Date();
  return d.toISOString().slice(0,10);
}

function last7DayAverage(exerciseId = null) {
  const since = Date.now() - (7 * 24 * 3600 * 1000);
  const items = state.sessions.filter(s => new Date(s.date).getTime() >= since && (!exerciseId || s.exerciseId === exerciseId));
  if (!items.length) return 0;
  return items.reduce((a,b)=>a + (b.ds || 0), 0) / items.length;
}

function lastConsecutiveLowDays() {
  const sorted = [...state.sessions].sort((a,b)=>new Date(b.date)-new Date(a.date));
  let count = 0;
  for (const s of sorted) {
    const avg = s.avg7 || 0;
    if (avg > 0 && s.ds < avg * 0.8) count++;
    else break;
  }
  return count;
}

function computeRedFlag() {
  state.redFlag = lastConsecutiveLowDays() >= 3;
}

function currentExercise() {
  if (state.draft?.exerciseId) return EXERCISES.find(e => e.id === state.draft.exerciseId);
  return EXERCISES[state.pointer] || EXERCISES[0];
}

function render() {
  saveState();
  computeRedFlag();
  switch(state.view) {
    case 'onboarding': return renderOnboarding();
    case 'settings': return renderSettings();
    case 'select': return renderSelect();
    case 'sessionSetup': return renderSessionSetup();
    case 'anchor': return renderAnchor();
    case 'rest': return renderRest();
    case 'myo': return renderMyo();
    case 'summary': return renderSummary();
    case 'history': return renderHistory();
    default: return renderHome();
  }
}

function nav(title, right='') {
  return `<div class="topnav"><button class="icon-btn" data-action="back">Back</button><div class="tag">${title}</div>${right || '<div style="width:32px"></div>'}</div>`;
}

function renderOnboarding() {
  const step = ONBOARDING[state.onboardingIndex];
  app.innerHTML = `
    <div class="screen center">
      <div class="card">
        <div class="title">${step.title}</div>
        <p class="subtitle" style="margin-top:16px">${step.body}</p>
      </div>
      <div class="onboard-dots">
        ${ONBOARDING.map((_,i)=>`<div class="dot ${i===state.onboardingIndex?'on':''}"></div>`).join('')}
      </div>
      <div class="footer-actions">
        ${state.onboardingIndex > 0 ? '<button class="btn secondary full" data-action="onboard-prev">Previous</button>' : ''}
        <button class="btn primary full" data-action="onboard-next">${state.onboardingIndex === ONBOARDING.length - 1 ? 'Continue to Setup' : 'Next'}</button>
      </div>
    </div>
  `;
}

function renderSettings() {
  app.innerHTML = `
    <div class="screen">
      ${nav('Profile Setup')}
      <div class="card">
        <div class="title">Your profile</div>
        <p class="subtitle">These values help calculate your Mechanical Load Score and Density Score.</p>
        <div class="grid" style="margin-top:14px">
          <label>Bodyweight (kg)
            <input id="bodyweight" type="number" min="20" max="300" step="0.1" value="${state.user.bodyweight || ''}" placeholder="e.g. 82.5">
          </label>
          <label>Default external load (kg)
            <input id="defaultLoad" type="number" min="0" max="300" step="0.5" value="${state.user.defaultLoad || '0'}" placeholder="0">
          </label>
          <label>Rotation mode
            <select id="rotationMode">
              <option value="fixed" ${state.rotationMode === 'fixed' ? 'selected':''}>Fixed Pentagon rotation</option>
              <option value="individual" ${state.rotationMode === 'individual' ? 'selected':''}>Individual exercise choice</option>
            </select>
          </label>
        </div>
      </div>
      <div class="footer-actions">
        <button class="btn primary full" data-action="save-settings">Save and Continue</button>
      </div>
    </div>
  `;
}

function pentagonSVG() {
  const pts = [
    [150,20],[270,105],[225,245],[75,245],[30,105]
  ];
  const active = state.pointer;
  return `
  <svg viewBox="0 0 300 280" width="100%" style="max-width:320px">
    <polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#3A3A3C" stroke-width="2"/>
    ${pts.map((p,i)=>`
      <circle class="vertex-circle ${state.sessions.some(s=>s.exerciseId===EXERCISES[i].id)?'done':''} ${i===active?'active':''}" cx="${p[0]}" cy="${p[1]}" r="22"></circle>
      <text class="vertex-label" x="${p[0]}" y="${p[1]+42}" text-anchor="middle">${EXERCISES[i].name.split(' ')[0]}</text>
    `).join('')}
    <text class="center-score" x="150" y="128" text-anchor="middle">${last7DayAverage().toFixed(1)}</text>
    <text x="150" y="150" text-anchor="middle" style="fill:#8d8d93;font-size:12px">7-day avg DS</text>
  </svg>`;
}

function renderHome() {
  const ex = EXERCISES[state.pointer];
  const doneToday = state.sessions.filter(s => s.date.slice(0,10) === todayStr()).map(s=>s.exerciseId);
  app.innerHTML = `
    <div class="screen">
      <div class="topnav">
        <div class="tag">Squat Tribe</div>
        <button class="icon-btn" data-action="open-settings">Profile</button>
      </div>

      ${state.redFlag ? `<div class="notice red"><strong>Recovery Mission</strong><div class="small" style="margin-top:8px">Your Density Score has been low versus your recent average for 3 consecutive sessions. Today, choose light mobility, isometric holds, or take a recovery day.</div></div>`:''}

      <div class="card">
        <div class="title">Pentagon Protocol</div>
        <p class="subtitle">Current exercise: <strong>${ex.name}</strong></p>
        <div class="pent-wrap">${pentagonSVG()}</div>
        <div class="row between">
          <div class="tag">Mode: ${state.rotationMode === 'fixed' ? 'Fixed' : 'Individual'}</div>
          <div class="tag">${doneToday.length} logged today</div>
        </div>
      </div>

      <div class="exercise-card active">
        <img src="${ex.image}" alt="${ex.name}">
        <div>
          <div class="exercise-name">${ex.name}</div>
          <div class="exercise-meta">${ex.type === 'unilateral' ? 'Unilateral · weaker leg first' : 'Bilateral'} · coefficient ${ex.coefficient.toFixed(2)}</div>
        </div>
      </div>

      <div class="grid two">
        <div class="kpi"><div class="label">7-day average</div><div class="value">${last7DayAverage(ex.id).toFixed(1)}</div></div>
        <div class="kpi"><div class="label">Last session DS</div><div class="value">${([ ...state.sessions].reverse().find(s=>s.exerciseId===ex.id)?.ds || 0).toFixed(1)}</div></div>
      </div>

      <div class="footer-actions">
        <button class="btn primary full" data-action="start-session">Start Session</button>
        ${state.rotationMode === 'individual' ? '<button class="btn secondary full" data-action="choose-exercise">Choose Exercise</button>':''}
        <button class="btn secondary full" data-action="view-history">History</button>
      </div>
    </div>
  `;
}

function renderSelect() {
  app.innerHTML = `
    <div class="screen">
      ${nav('Choose Exercise')}
      <div class="grid">
        ${EXERCISES.map((e, i)=>`
          <button class="exercise-card ${i===state.pointer?'active':''}" data-action="pick-exercise" data-id="${e.id}" style="text-align:left">
            <img src="${e.image}" alt="${e.name}">
            <div>
              <div class="exercise-name">${e.name}</div>
              <div class="exercise-meta">${e.type === 'unilateral' ? 'Unilateral' : 'Bilateral'} · coefficient ${e.coefficient.toFixed(2)}</div>
            </div>
          </button>
        `).join('')}
      </div>
    </div>
  `;
}

function renderSessionSetup() {
  const ex = currentExercise();
  app.innerHTML = `
    <div class="screen">
      ${nav('Session Setup')}
      <img class="hero-image" src="${ex.image}" alt="${ex.name}">
      <div class="card">
        <div class="title">${ex.name}</div>
        <p class="subtitle">${ex.type === 'unilateral'
          ? 'Select your weaker leg for this session, then begin on that side. The lower-performing side will govern the Myo target.'
          : 'Set your load, then begin your Anchor Set.'}</p>
        <div class="grid" style="margin-top:14px">
          <label>External load today (kg)
            <input id="session-load" type="number" min="0" max="500" step="0.5" value="${state.draft?.externalLoad ?? state.user.defaultLoad ?? 0}">
          </label>
          ${ex.type === 'unilateral' ? `
            <label>Weaker leg
              <select id="weaker-leg">
                <option value="">Select weaker leg</option>
                <option value="left" ${state.draft?.weakerLeg==='left'?'selected':''}>Left</option>
                <option value="right" ${state.draft?.weakerLeg==='right'?'selected':''}>Right</option>
              </select>
            </label>
          ` : ''}
        </div>
      </div>
      <div class="footer-actions">
        <button class="btn primary full" data-action="confirm-setup">Start Anchor</button>
      </div>
    </div>
  `;
}

let countdownHandle = null;
let anchorInterval = null;

function renderAnchor() {
  const ex = currentExercise();
  const d = state.draft || {};
  const unilateralInputs = ex.type === 'unilateral' ? `
    <div class="grid two">
      <label>${d.anchorSideStep === 'first' ? 'Weaker leg reps' : 'Other leg reps'}
        <input id="reps-a" type="number" min="0" step="1" value="${d.anchorRepsA ?? ''}">
      </label>
      <label>${d.anchorSideStep === 'first' ? 'Other leg reps' : 'Weaker leg reps'}
        <input id="reps-b" type="number" min="0" step="1" value="${d.anchorRepsB ?? ''}">
      </label>
    </div>
  ` : `
    <label>Total reps completed
      <input id="reps-main" type="number" min="0" step="1" value="${d.anchorReps ?? ''}">
    </label>
  `;
  app.innerHTML = `
    <div class="screen">
      ${nav('Anchor Set')}
      <img class="hero-image" src="${ex.image}" alt="${ex.name}">
      <div class="card">
        <div class="row between"><div class="tag">${ex.name}</div><div class="tag">${ex.type === 'unilateral' ? 'Weaker leg first' : 'Bilateral'}</div></div>
        <div style="text-align:center;margin-top:12px">
          <div class="small">Anchor duration</div>
          <div class="metric big-metric" id="anchor-time">${formatTime(d.anchorElapsed || 0)}</div>
        </div>
        <div class="footer-actions" style="margin-top:14px">
          ${!d.anchorRunning ? '<button class="btn primary full" data-action="anchor-start-clock">Start Anchor Timer</button>' : '<button class="btn warn full" data-action="anchor-stop-clock">Stop Timer</button>'}
        </div>
        <hr class="sep">
        <div class="grid">${unilateralInputs}</div>
      </div>
      <div class="footer-actions">
        <button class="btn primary full" data-action="finish-anchor">Save Anchor and Start Rest</button>
      </div>
    </div>
  `;
  if (d.anchorRunning) startAnchorTicker();
}

function startAnchorTicker() {
  if (anchorInterval) clearInterval(anchorInterval);
  anchorInterval = setInterval(() => {
    if (!state.draft?.anchorRunning) return clearInterval(anchorInterval);
    state.draft.anchorElapsed = (state.draft.anchorElapsed || 0) + 1;
    const el = $('#anchor-time');
    if (el) el.textContent = formatTime(state.draft.anchorElapsed);
  }, 1000);
}

function renderRest() {
  const d = state.draft;
  app.innerHTML = `
    <div class="screen center">
      ${nav('Adaptive Rest')}
      <div class="timer-ring pulse">
        <div style="text-align:center">
          <div class="small">Rest time</div>
          <div class="metric big-metric" id="rest-time">${formatTime(d.restRemaining || 0)}</div>
          <div class="small" style="margin-top:8px">1:1 work to rest</div>
        </div>
      </div>
      <div class="card">
        <div class="title" style="font-size:22px">Recover, then prepare</div>
        <p class="subtitle">When the countdown reaches zero, begin your first Myo set.</p>
      </div>
      <div class="footer-actions">
        <button class="btn secondary full" data-action="skip-rest">Skip Rest</button>
      </div>
    </div>
  `;
  if (countdownHandle) clearInterval(countdownHandle);
  countdownHandle = setInterval(() => {
    state.draft.restRemaining -= 1;
    $('#rest-time').textContent = formatTime(state.draft.restRemaining);
    if (state.draft.restRemaining <= 0) {
      clearInterval(countdownHandle);
      vibrate([100,40,100]);
      state.view = 'myo';
      render();
    }
  }, 1000);
}

function renderMyo() {
  const d = state.draft;
  const fatiguePct = Math.min(100, (d.strikes / 2) * 100 + ((d.myoSets?.length || 0) * 8));
  app.innerHTML = `
    <div class="screen">
      ${nav('Myo Sets')}
      <div class="card">
        <div class="row between"><div class="tag">Target reps</div><div class="metric" style="font-size:26px">${d.myoTarget}</div></div>
        <div style="margin-top:14px">
          <div class="row between"><div class="small">Fatigue bar</div><div class="small">${d.strikes} / 2 strikes</div></div>
          <div class="progress" style="margin-top:8px"><div class="bar ${d.strikes>0?'red':''}" style="width:${fatiguePct}%"></div></div>
        </div>
        ${d.exerciseType === 'unilateral'
          ? `<div class="notice" style="margin-top:14px"><strong>Select your weaker leg first</strong><div class="small" style="margin-top:6px">Log weaker-side reps, then other-side reps. The lower side governs the strike logic.</div></div>
             <div class="grid two" style="margin-top:14px">
               <label>Weaker leg reps
                 <input id="myo-reps-a" type="number" min="0" step="1" value="">
               </label>
               <label>Other leg reps
                 <input id="myo-reps-b" type="number" min="0" step="1" value="">
               </label>
             </div>`
          : `<label style="margin-top:14px">Myo set reps
               <input id="myo-reps-main" type="number" min="0" step="1" value="">
             </label>`
        }
      </div>

      <div class="card">
        <div class="row between"><div class="small">Completed Myo sets</div><div class="small">${d.myoSets.length}</div></div>
        ${d.myoSets.length
          ? d.myoSets.map((s,i)=>`<div class="history-item" style="margin-top:10px">Set ${i+1}: ${s.display}</div>`).join('')
          : '<div class="small" style="margin-top:10px">No Myo sets logged yet.</div>'}
      </div>

      <div class="footer-actions">
        <button class="btn primary full" data-action="log-myo">Set Complete</button>
        <button class="btn secondary full" data-action="done-session">I&apos;m Done</button>
      </div>
    </div>
  `;
}

function renderSummary() {
  const s = state.draft.summary;
  app.innerHTML = `
    <div class="screen">
      ${nav('Session Summary')}
      <div class="card">
        <div class="title">${s.exerciseName}</div>
        <div class="grid two" style="margin-top:14px">
          <div class="kpi"><div class="label">MLS</div><div class="value">${s.mls.toFixed(1)}</div></div>
          <div class="kpi"><div class="label">DS</div><div class="value">${s.ds.toFixed(1)}</div></div>
          <div class="kpi"><div class="label">Total reps</div><div class="value">${s.totalReps}</div></div>
          <div class="kpi"><div class="label">Active time</div><div class="value">${formatTime(s.activeSeconds)}</div></div>
        </div>
        <div class="notice ${s.lowVsAvg ? 'red':''}" style="margin-top:14px">
          <strong>${s.lowVsAvg ? 'Reduced density versus average' : 'Solid session logged'}</strong>
          <div class="small" style="margin-top:6px">${s.message}</div>
        </div>
      </div>
      <div class="footer-actions">
        <button class="btn primary full" data-action="log-session">Log Session</button>
      </div>
    </div>
  `;
}

function renderHistory() {
  const items = [...state.sessions].sort((a,b)=>new Date(b.date)-new Date(a.date));
  app.innerHTML = `
    <div class="screen">
      ${nav('History')}
      <div class="grid">
        ${items.length ? items.map(s=>`
          <div class="history-item">
            <div class="row between"><strong>${s.exerciseName}</strong><span class="small">${new Date(s.date).toLocaleDateString()}</span></div>
            <div class="small" style="margin-top:8px">DS ${s.ds.toFixed(1)} · MLS ${s.mls.toFixed(1)} · reps ${s.totalReps}</div>
          </div>
        `).join('') : '<div class="card"><div class="subtitle">No sessions logged yet.</div></div>'}
      </div>
    </div>
  `;
}

function formatTime(totalSeconds) {
  const s = Math.max(0, Math.floor(totalSeconds || 0));
  const mm = String(Math.floor(s / 60)).padStart(2, '0');
  const ss = String(s % 60).padStart(2, '0');
  return `${mm}:${ss}`;
}

function openSession(exerciseId = null) {
  const ex = exerciseId ? EXERCISES.find(e => e.id === exerciseId) : EXERCISES[state.pointer];
  state.draft = {
    exerciseId: ex.id,
    exerciseType: ex.type,
    exerciseName: ex.name,
    externalLoad: Number(state.user.defaultLoad || 0),
    weakerLeg: '',
    anchorElapsed: 0,
    anchorRunning: false,
    anchorReps: null,
    anchorRepsA: null,
    anchorRepsB: null,
    myoTarget: null,
    myoSets: [],
    strikes: 0,
  };
  state.view = 'sessionSetup';
  render();
}

function finishAnchor() {
  const ex = currentExercise();
  const d = state.draft;
  const bodyweight = Number(state.user.bodyweight || 0);
  const load = Number(d.externalLoad || 0);
  if (!bodyweight) return alert('Please set your bodyweight first.');
  if (!d.anchorElapsed || d.anchorElapsed < 1) return alert('Run the Anchor timer first.');
  let anchorReps;
  if (ex.type === 'unilateral') {
    const a = Number($('#reps-a')?.value || d.anchorRepsA || 0);
    const b = Number($('#reps-b')?.value || d.anchorRepsB || 0);
    if (!a || !b) return alert('Enter reps for both sides.');
    d.anchorRepsA = a; d.anchorRepsB = b;
    anchorReps = Math.min(a,b);
  } else {
    const reps = Number($('#reps-main')?.value || d.anchorReps || 0);
    if (!reps) return alert('Enter total reps.');
    d.anchorReps = reps;
    anchorReps = reps;
  }
  d.effectiveLoad = load + bodyweight * ex.coefficient;
  d.anchorEffectiveReps = anchorReps;
  d.myoTarget = Math.max(3, Math.round(anchorReps * 0.25));
  d.restRemaining = d.anchorElapsed;
  state.view = 'rest';
  render();
}

function logMyoSet() {
  const d = state.draft;
  let actual;
  let display;
  if (d.exerciseType === 'unilateral') {
    const a = Number($('#myo-reps-a').value || 0);
    const b = Number($('#myo-reps-b').value || 0);
    if (!a || !b) return alert('Enter both weaker-side and other-side reps.');
    actual = Math.min(a,b);
    display = `${a} / ${b}`;
  } else {
    const reps = Number($('#myo-reps-main').value || 0);
    if (!reps) return alert('Enter reps for the set.');
    actual = reps;
    display = String(reps);
  }
  d.myoSets.push({ actual, display });
  if (actual < d.myoTarget) {
    d.strikes += 1;
    vibrate([80,40,80]);
  } else {
    d.strikes = 0;
  }
  if (d.strikes >= 2) {
    return prepareSummary(true);
  }
  // 15-second breath timer
  let secs = 15;
  app.innerHTML = `
    <div class="screen center">
      ${nav('Breath Timer')}
      <div class="timer-ring pulse">
        <div style="text-align:center">
          <div class="small">Breathe</div>
          <div class="metric big-metric" id="breath-time">${formatTime(secs)}</div>
          <div class="small" style="margin-top:8px">Next Myo set soon</div>
        </div>
      </div>
    </div>`;
  if (countdownHandle) clearInterval(countdownHandle);
  countdownHandle = setInterval(() => {
    secs -= 1;
    $('#breath-time').textContent = formatTime(secs);
    if (secs <= 0) {
      clearInterval(countdownHandle);
      vibrate([100,40,100]);
      renderMyo();
    }
  },1000);
}

function prepareSummary(autoTerminated = false) {
  const d = state.draft;
  const ex = currentExercise();
  const anchorReps = ex.type === 'unilateral' ? Math.min(d.anchorRepsA, d.anchorRepsB) : d.anchorReps;
  const myoTotal = d.myoSets.reduce((sum,s)=>sum+s.actual,0);
  const totalReps = anchorReps + myoTotal;
  const activeSeconds = d.anchorElapsed + d.myoSets.length * 15;
  const mls = d.effectiveLoad * totalReps;
  const ds = activeSeconds > 0 ? mls / activeSeconds : 0;
  const avg7 = last7DayAverage(ex.id);
  const lowVsAvg = avg7 > 0 && ds < avg7 * 0.8;
  d.summary = {
    exerciseId: ex.id,
    exerciseName: ex.name,
    exerciseType: ex.type,
    date: new Date().toISOString(),
    externalLoad: Number(d.externalLoad),
    coefficient: ex.coefficient,
    effectiveLoad: d.effectiveLoad,
    anchorElapsed: d.anchorElapsed,
    anchorRepsA: d.anchorRepsA,
    anchorRepsB: d.anchorRepsB,
    anchorReps,
    myoSets: d.myoSets,
    totalReps,
    activeSeconds,
    mls, ds, avg7,
    lowVsAvg,
    message: autoTerminated
      ? 'Two consecutive under-target Myo sets triggered auto-termination. This protects session quality.'
      : lowVsAvg
        ? 'Today was below your recent average. Consider keeping the next session conservative.'
        : 'Your session was logged with stable density. Keep building consistency.',
  };
  state.view = 'summary';
  render();
}

function logSession() {
  const s = state.draft.summary;
  s.avg7 = s.avg7 || last7DayAverage(s.exerciseId);
  state.sessions.push(s);
  if (state.rotationMode === 'fixed') {
    const idx = EXERCISES.findIndex(e=>e.id===s.exerciseId);
    state.pointer = (idx + 1) % EXERCISES.length;
  } else {
    state.pointer = EXERCISES.findIndex(e=>e.id===s.exerciseId);
  }
  state.draft = null;
  vibrate(200);
  state.view = 'home';
  render();
}

document.addEventListener('click', (e) => {
  const action = e.target.closest('[data-action]')?.dataset.action;
  if (!action) return;
  if (action === 'onboard-next') {
    if (state.onboardingIndex < ONBOARDING.length - 1) state.onboardingIndex++;
    else state.view = 'settings';
  }
  if (action === 'onboard-prev') state.onboardingIndex = Math.max(0, state.onboardingIndex - 1);
  if (action === 'save-settings') {
    state.user.bodyweight = $('#bodyweight').value;
    state.user.defaultLoad = $('#defaultLoad').value || '0';
    state.rotationMode = $('#rotationMode').value;
    state.onboarded = true;
    state.view = 'home';
  }
  if (action === 'open-settings') state.view = 'settings';
  if (action === 'back') {
    if (['settings','select','history'].includes(state.view)) state.view = 'home';
    else if (state.view === 'sessionSetup') state.view = 'home';
    else if (['anchor','rest','myo','summary'].includes(state.view)) state.view = 'sessionSetup';
  }
  if (action === 'start-session') openSession();
  if (action === 'choose-exercise') state.view = 'select';
  if (action === 'pick-exercise') {
    state.pointer = EXERCISES.findIndex(x=>x.id === e.target.closest('[data-id]').dataset.id);
    openSession(EXERCISES[state.pointer].id);
  }
  if (action === 'confirm-setup') {
    state.draft.externalLoad = Number($('#session-load').value || 0);
    if (state.draft.exerciseType === 'unilateral') {
      state.draft.weakerLeg = $('#weaker-leg').value;
      if (!state.draft.weakerLeg) return alert('Please choose your weaker leg.');
    }
    state.view = 'anchor';
  }
  if (action === 'anchor-start-clock') {
    state.draft.anchorRunning = true;
    startAnchorTicker();
    render();
  }
  if (action === 'anchor-stop-clock') {
    state.draft.anchorRunning = false;
    if (anchorInterval) clearInterval(anchorInterval);
    render();
  }
  if (action === 'finish-anchor') finishAnchor();
  if (action === 'skip-rest') { if (countdownHandle) clearInterval(countdownHandle); state.view='myo'; render(); }
  if (action === 'log-myo') logMyoSet();
  if (action === 'done-session') prepareSummary(false);
  if (action === 'log-session') logSession();
  if (action === 'view-history') state.view = 'history';
});

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js'));
}

render();
